style.css:
@-moz-document url("chrome://new-tab-page/"), url-prefix("https://www.google.com/_/chrome/newtab") {
/* 1. Background Utama */
    body, ntp-app {
        background-color: #222831 !important;
        background-image: radial-gradient(circle at 50% 50%, #393E46 0%, #222831 80%) !important;
        color: #EEEEEE !important;
        font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important;
    }

    /* 2. Kustomisasi Search Bar (Pusat Perhatian) */
    ntp-search-box, #searchbox, .search-box {
        background: rgba(57, 62, 70, 0.7) !important;
        backdrop-filter: blur(10px) !important;
        border: 2px solid #393E46 !important;
        border-radius: 24px !important;
        box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37), 
                    0 0 0 1px rgba(0, 173, 181, 0.1) !important;
        transition: all 0.4s ease-in-out !important;
        transform: translateY(-20px) !important; /* Menaikkan sedikit posisinya biar keren */
    }

    /* Efek Glow saat Search Bar di-focus/hover */
    ntp-search-box:hover, ntp-search-box:focus-within {
        border-color: #00ADB5 !important;
        box-shadow: 0 0 20px rgba(0, 173, 181, 0.4), 
                    0 8px 32px 0 rgba(0, 0, 0, 0.5) !important;
        transform: translateY(-23px) scale(1.02) !important;
    }

    /* Teks di dalam Search Bar */
    ntp-search-box input, #searchbox input {
        color: #EEEEEE !important;
    }
    
    ntp-search-box input::placeholder {
        color: rgba(238, 238, 238, 0.6) !important;
    }

    /* 3. Kustomisasi Shortcut / Most Visited Tiles */
    ntp-tiles-container, .tile, ntp-tile {
        background: transparent !important;
    }

    .tile--card, ntp-tile .tile {
        background-color: #393E46 !important;
        border-radius: 16px !important;
        border: 1px solid transparent !important;
        transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s, border-color 0.3s !important;
    }

    /* Efek Hover pada Shortcut */
    .tile--card:hover, ntp-tile .tile:hover {
        transform: translateY(-8px) !important;
        border-color: #00ADB5 !important;
        box-shadow: 0 10px 20px rgba(0, 173, 181, 0.2) !important;
        background-color: rgba(57, 62, 70, 0.9) !important;
    }

    /* Judul Text Shortcut */
    .tile-title span, ntp-tile .title {
        color: #EEEEEE !important;
        font-weight: 500 !important;
        text-shadow: 0 2px 4px rgba(0,0,0,0.3) !important;
    }

    /* 4. Logo Google (Opsional: Memberikan efek siluet/glow minimalis) */
    #logo, .logo, ntp-logo {
        filter: drop-shadow(0px 0px 8px rgba(0, 173, 181, 0.3)) !important;
        margin-bottom: 40px !important;
    }

    /* 5. Tombol Kustomisasi di Pojok Kanan Bawah */
    #customize-button, .customize-button, ntp-customize-chrome-button {
        background-color: #393E46 !important;
        color: #00ADB5 !important;
        border: 1px solid #00ADB5 !important;
        border-radius: 8px !important;
        transition: all 0.3s ease !important;
    }

    #customize-button:hover, ntp-customize-chrome-button:hover {
        background-color: #00ADB5 !important;
        color: #222831 !important;
        box-shadow: 0 0 15px rgba(0, 173, 181, 0.5) !important;
    }
    
    /* 6. Hilangkan elemen mengganggu/bising di latar belakang jika ada */
    #ntp-contents {
        margin-top: 5vh !important;
    }
}
